#[derive(Parser)]
#[command(name = "notekeep")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    List(ListArgs),
    // ... other subcommands (add, edit, etc.)
}

#[derive(Parser)]
struct ListArgs {
    /// Filter notes by exact tag match
    #[arg(long)]
    tag: Option<String>,

    // ... other list options (e.g., --limit, --sort, --pinned)
}

fn main() {
    let cli = Cli::parse();

    match cli.command {
        Commands::List(args) => {
            // Replace with your actual data loading logic
            let notes = notekeep::load_notes(); 

            let filtered = match args.tag {
                Some(tag) => notekeep::filter_by_tag(&notes, &tag),
                None => notes.iter().collect(),
            };

            // Render/display `filtered` notes
            for note in &filtered {
                println!("{}: {}", note.title, note.body);
            }
        }
        // ...
    }
}
```

