```rust
use crate::{Note, pin, unpin, ordered_pinned_first};

#[test]
fn test_pin_sets_flag() {
    let mut notes = vec![
        Note { id: "alpha".to_string(), pinned: false },
        Note { id: "beta".to_string(), pinned: false },
    ];
    pin(&mut notes, "alpha");
    assert!(notes[0].pinned);
    assert!(!notes[1].pinned);
}

#[test]
fn test_unpin_clears_flag() {
    let mut notes = vec![
        Note { id: "alpha".to_string(), pinned: true },
        Note { id: "beta".to_string(), pinned: false },
    ];
    unpin(&mut notes, "alpha");
    assert!(!notes[0].pinned);
    assert!(!notes[1].pinned);
}

#[test]
fn test_pin_nonexistent_is_noop() {
    let mut notes = vec![
        Note { id: "alpha".to_string(), pinned: false },
    ];
    pin(&mut notes, "nonexistent");
    assert!(!notes[0].pinned);
}

#[test]
fn test_unpin_nonexistent_is_noop() {
    let mut notes = vec![
        Note { id: "alpha".to_string(), pinned: true },
    ];
    unpin(&mut notes, "nonexistent");
    assert!(notes[0].pinned);
}

#[test]
fn test_ordered_pinned_first_basic() {
    let notes = vec![
        Note { id: "1".to_string(), pinned: false },
        Note { id: "2".to_string(), pinned: true },
        Note { id: "3".to_string(), pinned: false },
        Note { id: "4".to_string(), pinned: true },
    ];
    let ordered = ordered_pinned_first(&notes);
    let ids: Vec<&str> = ordered.iter().map(|n| n.id.as_str()).collect();
    assert_eq!(ids, vec!["2", "4", "1", "3"]);
}

#[test]
fn test_ordered_pinned_first_preserves_relative_order() {
    let notes = vec![
        Note { id: "a".to_string(), pinned: true },
        Note { id: "b".to_string(), pinned: false },
        Note { id: "c".to_string(), pinned: true },
        Note { id: "d".to_string(), pinned: false },
    ];
    let ordered = ordered_pinned_first(&notes);
    let ids: Vec<&str> = ordered.iter().map(|n| n.id.as_str()).collect();
    // Pinned group: a, c (original order preserved)
    // Unpinned group: b, d (original order preserved)
    assert_eq!(ids, vec!["a", "c", "b", "d"]);
}

#[test]
fn test_ordered_pinned_first_empty() {
    let notes: Vec<Note> = vec![];
    let ordered = ordered_pinned_first(&notes);
    assert!(ordered.is_empty());
}

#[test]
fn test_ordered_pinned_first_all_pinned() {
    let notes = vec![
        Note { id: "x".to_string(), pinned: true },
        Note { id: "y".to_string(), pinned: true },
    ];
    let ordered = ordered_pinned_first(&notes);
    let ids: Vec<&str> = ordered.iter().map(|n| n.id.as_str()).collect();
    assert_eq!(ids, vec!["x", "y"]);
}

#[test]
fn test_ordered_pinned_first_all_unpinned() {
    let notes = vec![
        Note { id: "x".to_string(), pinned: false },
        Note { id: "y".to_string(), pinned: false },
    ];
    let ordered = ordered_pinned_first(&notes);
    let ids: Vec<&str> = ordered.iter().map(|n| n.id.as_str()).collect();
    assert_eq!(ids, vec!["x", "y"]);
}
```

